SELECT p.id AS position_id, SECOND(e.observed_at) <= 1 AS minute_boundary, COUNT(*) AS n, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at))/1000,1) AS avg_ms, MIN(TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at))/1000 AS min_ms, MAX(TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at))/1000 AS max_ms, SUM(e.created_at < e.observed_at) AS negative_n FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN DATE_SUB(p.opened_at, INTERVAL 5 MINUTE) AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, minute_boundary ORDER BY p.id, minute_boundary;